class Api:
    """Every API method as a Python method. Give the parameters as keyword arguments."""

    def __init__(self, call: Callable[[str, dict[str, Any] | None], Any]) -> None:
        self._call = call

    def describe(self, **params: "Unpack[DescribeParams]") -> Any:
        """List methods and command examples.

        JSON-RPC method ``describe``."""
        return self._call("describe", params or None)

    def execute(self, **params: "Unpack[ExecuteParams]") -> Any:
        """Run one command. params: {command: Command}. Returns {created: [id]}.

        JSON-RPC method ``execute``."""
        return self._call("execute", params or None)

    def undo(self, **params: "Unpack[UndoParams]") -> Any:
        """Undo the last command. Returns {done: bool}.

        JSON-RPC method ``undo``."""
        return self._call("undo", params or None)

    def redo(self, **params: "Unpack[RedoParams]") -> Any:
        """Redo the last undone command. Returns {done: bool}.

        JSON-RPC method ``redo``."""
        return self._call("redo", params or None)

    def document_summary(self, **params: "Unpack[DocumentSummaryParams]") -> Any:
        """Layers, classes, object counts and drawing bounds.

        JSON-RPC method ``document.summary``."""
        return self._call("document.summary", params or None)

    def document_get(self, **params: "Unpack[DocumentGetParams]") -> Any:
        """The full document as JSON, without its versions (they have their own methods: version.*).

        JSON-RPC method ``document.get``."""
        return self._call("document.get", params or None)

    def document_load(self, **params: "Unpack[DocumentLoadParams]") -> Any:
        """Replace the document. params: {document}. Clears the undo history. If the document has no `history` field (document.get leaves it out), the versions of the current document stay: they are written for the new drawing. A document with a `history` field brings its own versions. Returns {ok, notes?}; notes lists values that were repaired instead of refusing the document (an invalid 3D look of a site model goes back to its defaults) and what could not be read of its versions.

        JSON-RPC method ``document.load``."""
        return self._call("document.load", params or None)

    def file_save(self, **params: "Unpack[FileSaveParams]") -> Any:
        """Save the document atomically (the old file stays as .bak). params: {path, format?}. format is "container" (a ZIP file with the drawing, the pictures and the versions; the default) or "json" (one readable JSON file with the pictures as base64, for version control and diffs). Without format the extension decides: .json is JSON, anything else the container. Returns {ok, format}.

        JSON-RPC method ``file.save``."""
        return self._call("file.save", params or None)

    def file_open(self, **params: "Unpack[FileOpenParams]") -> Any:
        """Open a document of either form (told by the first bytes). params: {path}. The pictures of a container stay in the file until they are used. A file over the size limit, or a container whose entries together are over it, is refused with the way to raise the limit. Returns {ok, format, notes?}.

        JSON-RPC method ``file.open``."""
        return self._call("file.open", params or None)

    def objects_list(self, **params: "Unpack[ObjectsListParams]") -> Any:
        """Objects. params: {layer?, class?, kind?}.

        JSON-RPC method ``objects.list``."""
        return self._call("objects.list", params or None)

    def objects_get(self, **params: "Unpack[ObjectsGetParams]") -> Any:
        """One object. params: {id, sources? (true shows the import tags of the sources of a site model: data.import_sources, one entry for each point and line; by default the answer only counts them)}.

        JSON-RPC method ``objects.get``."""
        return self._call("objects.get", params or None)

    def selection_get(self, **params: "Unpack[SelectionGetParams]") -> Any:
        """Selected object IDs.

        JSON-RPC method ``selection.get``."""
        return self._call("selection.get", params or None)

    def selection_set(self, **params: "Unpack[SelectionSetParams]") -> Any:
        """Select objects. params: {ids: [id]}. Objects of grey layers and classes cannot be selected.

        JSON-RPC method ``selection.set``."""
        return self._call("selection.set", params or None)

    def render_svg(self, **params: "Unpack[RenderSvgParams]") -> Any:
        """SVG image of visible objects. params: {width?: px, compare?}. With compare {from, to, mode?, hide_unchanged?, ...} (see describe.review.compare) the plan of `to` is drawn with the changes since `from`: added objects green, changed objects orange, removed objects as red dashed ghosts, each with a mark (+, ~, -) and a legend with the counts. Returns {svg, compare?}.

        JSON-RPC method ``render.svg``."""
        return self._call("render.svg", params or None)

    def render_png(self, **params: "Unpack[RenderPngParams]") -> Any:
        """PNG image of the 3D model. params: {view?, width?, height?, projection?, mode?, render_style?, samples?}. view is one of view.list (default: the current view), projection is ortho or perspective, mode is shaded, wireframe, hidden_line or dashed_hidden_line, render_style is a render style of the document (ID or name) or a built-in one (Realistic draws materials, the sun and shadows); without it the active style is used. samples is 1 to 3 (anti-aliasing). Size is 16 to 2048 px per side and at most 4 million px (default 800x600), larger sizes are scaled down. compare {from, to, mode?, hide_unchanged?, ...} (see describe.review.compare) draws `to` with the changes since `from`: added objects green, changed orange, removed objects as see-through red ghosts; with mode side_by_side it draws both sides next to each other with the same framing. render_style cannot be used with compare. Returns {png_base64, width, height, view, projection, mode, render_style (not with compare), compare?}.

        JSON-RPC method ``render.png``."""
        return self._call("render.png", params or None)

    def view_list(self, **params: "Unpack[ViewListParams]") -> Any:
        """Standard 3D views, projections and render modes, the saved views (saved_views: [{name}]; view.set takes their names) and the current view.

        JSON-RPC method ``view.list``."""
        return self._call("view.list", params or None)

    def view_set(self, **params: "Unpack[ViewSetParams]") -> Any:
        """Switch the view (also in the live app). params: {view?, projection?, mode?}. view is a name from view.list or the name of a saved view (view.list saved_views); top is the 2D plan in the app. A saved view sets the camera only (the plan middle and zoom in the app, or the 3D view, projection and mode): the layers and classes stay as they are, because changing them is an edit of the document (use saved_view.restore for that), and the answer has layers_not_applied: true when the saved view holds visibility. Returns the current view.

        JSON-RPC method ``view.set``."""
        return self._call("view.set", params or None)

